#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int makeArrayPositive(vector<int>& nums) {
        int l = -1;
        int ans = 0;
        long long pre_mx = 0, s = 0;
        for (int r = 0; r < (int)nums.size(); ++r) {
            s += nums[r];
            if (r - l > 2 && s <= pre_mx) {
                ans++;
                l = r;
                s = nums[r];
                pre_mx = 0;
            } else {
                pre_mx = min(pre_mx, s);
            }
        }
        return ans;
    }
};

class Solution {
    public int makeArrayPositive(int[] nums) {
        int l = -1;
        int ans = 0;
        long pre_mx = 0, s = 0;
        for (int r = 0; r < nums.length; r++) {
            s += nums[r];
            if (r - l > 2 && s <= pre_mx) {
                ans++;
                l = r;
                s = nums[r];
                pre_mx = 0;
            } else {
                pre_mx = Math.min(pre_mx, s);
            }
        }
        return ans;
    }
}

